on conflict(day_number) do nothing;

select c.id,v.description,v.n from public.challenges c cross join (values
(1,'Tiene más de 5 años en COOPEBANACIO.'),(2,'Tiene una mascota.'),(3,'Practica algún deporte.'),
(4,'Tiene un hobby artístico.'),(5,'Ha trabajado en más de un área.'),(6,'Prefiere montaña antes que playa.'),
(7,'Toma café todos los días.'),(8,'Ha viajado fuera del país este año.'),(9,'Cumple años en el mismo semestre que vos.')
) as v(n,description) where c.day_number=5 on conflict(challenge_id,order_number) do nothing;
